from lib import *
S = SS('p65')
steps = [
    step("不改 User-Agent 时,各库在服务器日志(nginx 1.31.6 的 combined 格式)里的样子:requests 是 python-requests/2.34.2,urllib 是 Python-urllib/3.14,aiohttp 是 Python/3.14 aiohttp/3.14.3,curl_cffi 默认不带 User-Agent 头(日志里是 -),curl_cffi 用 impersonate='chrome' 时是 Mozilla/5.0 (Macintosh; … ) Chrome/146.0.0.0 Safari/537.36,手写请求不带头的也是 -。站长一眼能认出默认的库名;impersonate 的 Chrome 版本(146)和我机器上装的 Chrome(154)不一样,是 curl_cffi 自带的版本号。", t=tl(S(1)), done=lidx(S(1), '/a-requests'), b=bars([['requests', 1, 'python-requests/2.34.2'], ['urllib', 1, 'Python-urllib/3.14'], ['aiohttp', 1, 'Python/3.14 aiohttp/3.14.3'], ['curl_cffi 默认', 0, '(没有 UA 头)']], 1.2, done=[0, 1, 2], mark=[3]), kv=KV([['requests', 'python-requests/2.34.2'], ['curl_cffi 默认', '没有 User-Agent 头'], ['curl_cffi chrome', 'Chrome/146.0.0.0']], ['curl_cffi 默认'])),
    step("自报身份:User-Agent 写成 MyCrawler/1.0 (+https://example.org/bot.html; ops@example.org),并带 From: ops@example.org。combined 格式的日志里只有 User-Agent(整串原样,包括网址和邮箱);日志格式里加上 $http_from 才会记 From 头,带了的请求记 from=\"ops@example.org\",没带的是 -。From 头默认不在常见日志格式里,站长不专门配置就看不到。", t=tl(S(2)), done=lidx(S(2), 'withfrom:127.0.0.1 "GET /with-id'), mark=lidx(S(2), 'combined:"GET /with-id'), kv=KV([['combined 日志', '记完整 User-Agent,不记 From'], ['加 $http_from', '才会记 From'], ['UA 里的网址/邮箱', '整串原样出现在日志里']], ['加 $http_from'])),
    step("User-Agent 太长:nginx 默认 large_client_header_buffers 4 8k,每个请求头要放进一个 8 KiB 的缓冲。UA 长 1000、4000、8000、8100 字节都返回 200;8200 字节和 16000 字节返回 400 Bad Request。UA 里不要塞太多内容;这是 nginx 默认配置下的结果,别的服务器的限制不同。", t=tl(S(3)), done=lidx(S(3), 'UA 长  8100'), mark=lidx(S(3), 'UA 长  8200'), b=bars([['UA 长 8100 字节', 200, '200'], ['UA 长 8200 字节', 400, '400'], ['UA 长 16000 字节', 400, '400']], 450, done=[0], mark=[1, 2]), kv=KV([['≤ 8100 字节', '200 OK'], ['≥ 8200 字节', '400 Bad Request'], ['限制来自', 'nginx 默认的 8k 缓冲']], ['≥ 8200 字节'])),
    step("UA 里放中文:requests 传 str 抛 UnicodeEncodeError('latin-1' codec can't encode characters),没发出请求;requests 传 UTF-8 编码的 bytes 能发出,日志里是转义的 \\xE7\\x88\\xAC\\xE8\\x99\\xAB/1.0;urllib 传 str 同样抛 UnicodeEncodeError;aiohttp 传 str 能发出,日志里同样是 \\xE7\\x88\\xAC\\xE8\\x99\\xAB/1.0。含换行的 UA(想注入 X-Injected 头)requests 抛 InvalidHeader,没发出。UA 里用 ASCII;中文名字在服务器日志里是一串转义,看不懂。", t=tl(S(4)), done=lidx(S(4), 'aiohttp 中文'), mark=lidx(S(4), 'requests 中文(str)'), b=bars([['requests str', 0, '报错'], ['requests bytes', 1, '发出'], ['urllib str', 0, '报错'], ['aiohttp str', 1, '发出']], 1.2, mark=[0, 2], done=[1, 3]), kv=KV([['requests / urllib 传中文 str', 'UnicodeEncodeError'], ['requests bytes / aiohttp str', '发出,日志里是 \\xE7… 转义'], ['含换行', 'requests 抛 InvalidHeader']], ['requests / urllib 传中文 str'])),
    step("robots.txt 按 User-agent 匹配:这里 robots.txt 有 mycrawler 组(Disallow /private/)和 * 组(Disallow /)。标准库 urllib.robotparser:传 “MyCrawler” 或 “mycrawler/1.0” 或完整的 UA 字符串 “MyCrawler/1.0 (+https://…)”,/public 允许、/private/x 禁止(匹配了 mycrawler 组);传 Mozilla 兼容写法 “Mozilla/5.0 (compatible; MyCrawler/1.0; …)” 时落到 * 组,/public 也被禁止了。UA 要以产品名开头,robots.txt 里的名字才对得上(这是 urllib.robotparser 的行为,别的实现不一定)。", t=tl(S(5)), done=lidx(S(5), '只传产品名 MyCrawler'), mark=lidx(S(5), '传 Mozilla 兼容写法'), b=bars([['传 MyCrawler:/public 允许', 1, '允许'], ['传完整 UA(以产品名开头):允许', 1, '允许'], ['传 Mozilla 兼容写法:/public', 0, '被禁止']], 1.2, done=[0, 1], mark=[2]), kv=KV([['产品名开头', '匹配 mycrawler 组'], ['Mozilla/5.0 (compatible; …)', '落到 * 组,/public 被禁'], ['行为来自', 'urllib.robotparser']], ['Mozilla/5.0 (compatible; …)'])),
    step("站长视角:三种客户端各发 300 个请求,来自同一个 IP 127.0.0.1。按 IP 统计只有一行(900 个请求);按 User-Agent 统计是 3 行:python-requests/2.34.2 300、MyCrawler/1.0 (+https://example.org/bot.html; ops@example.org) 300、Chrome 的 UA 300。同一出口 IP 后面的多个客户端,站长靠 UA 区分;UA 是默认的库名时,站长只知道“有人在用 requests”,UA 里写了网址和邮箱才有人可以找。", t=tl(S(6)), done=lidx(S(6), '按 User-Agent 统计'), mark=lidx(S(6), '按来源 IP 统计'), b=bars([['按 IP 统计的行数', 1, '1'], ['按 User-Agent 统计的行数', 3, '3']], 3.2, mark=[0], done=[1]), kv=KV([['按来源 IP', '1 行,900 个请求'], ['按 User-Agent', '3 行,各 300'], ['UA 里有网址/邮箱', '站长能联系到']], ['按 User-Agent'])),
]
A = mkartp('p65', 65, '爬虫,User-Agent,From头,nginx,访问日志,robots.txt,联系方式,Python,真实验证,动画演示',
    '在本机 nginx 的访问日志里看各 HTTP 库默认的 User-Agent、自报身份的 UA 与 From 头怎么出现、UA 太长 nginx 默认从 8200 字节起返回 400、中文 UA 在 requests/urllib 里报错,以及 UA 的写法怎么影响 urllib.robotparser 的匹配。',
    '爬虫发出的每个请求都会在目标服务器的日志里留下一行。站长从这一行里能看到什么、认得出你是谁吗?这篇在本机 nginx 的访问日志里把常见库的 UA、自报身份的写法和几个边界情况逐个看一遍。',
    [('python-requests/2.34.2', 'requests 不改 UA 时服务器日志里的样子(curl_cffi 默认则根本没有 UA 头)'), ('8100 对 8200 字节', 'nginx 默认配置下,UA 8100 字节返回 200,8200 字节返回 400'), ('1 对 3', '同一个 IP 发来 900 个请求,按 IP 统计是 1 行,按 UA 统计是 3 行')],
    [('默认 UA', '<p>requests、urllib、aiohttp 的默认 UA 都带库名和版本(python-requests/2.34.2、Python-urllib/3.14、Python/3.14 aiohttp/3.14.3);curl_cffi 默认不带 UA 头;用 impersonate=\'chrome\' 则是它自带的那个 Chrome 版本(实验里 146,和我机器上的 Chrome 154 不同)。</p>'),
     ('自报身份', '<p>把爬虫名、说明页网址和联系邮箱写进 User-Agent,整串都会出现在站长的访问日志里。From 头也能带邮箱,但常见的日志格式不记它,要站长专门在 log_format 里加 $http_from。</p>'),
     ('长度', '<p>nginx 默认的 large_client_header_buffers 是 4 个 8k,一个请求头要放进一个缓冲:实验里 UA 8100 字节返回 200,8200 字节返回 400。别的服务器、CDN 的限制不同,我没有测。</p>'),
     ('非 ASCII', '<p>requests 和 urllib 把头值按 latin-1 编码,传中文 str 会抛 UnicodeEncodeError;requests 传 UTF-8 的 bytes、aiohttp 传 str 能发出,但服务器日志里是 \\xE7\\x88… 这样的转义,站长看不懂。含换行的头值 requests 会拒绝(InvalidHeader)。UA 用 ASCII 写。</p>'),
     ('和 robots.txt 的关系', '<p>robots.txt 里 User-agent 写的是产品名,客户端用什么字符串去匹配取决于实现。urllib.robotparser 取 UA 第一个 “/” 之前的部分(实验里 MyCrawler/1.0 (+…) 匹配到了 mycrawler 组),而 Mozilla/5.0 (compatible; MyCrawler/1.0) 这种写法取到的是 mozilla,落到 * 组。UA 以产品名开头,和你实际用的 robots 解析器对得上(第 26 篇讲了解析器的差别)。</p>'),
     ('站长怎么区分', '<p>一个出口 IP 后面可能有很多客户端,站长在日志里常常是按 UA 区分的。UA 只是默认库名时,站长只能知道“有人用 requests”;写了网址和邮箱,站长至少有地方可以联系。是否有人去看,我没有办法验证。</p>')],
    steps,
    [ENV_P + '。服务器是本机 nginx 1.31.6(只监听 127.0.0.1,combined 日志格式加一个记录 $http_from 的自定义格式),各客户端为 requests 2.34.2、urllib、aiohttp 3.14.3、curl_cffi 0.15.0;UA 超长的请求用裸套接字发;各情形跑一次(第六节每种 300 次)',
     '没有验证:真实站点对 UA 的处理(有的站按 UA 屏蔽、有的站根本不看);CDN、WAF 对超长 UA 或空 UA 的处理;邮件地址写进 UA 之后是否真有人联系;Apache、IIS 等其它服务器的头长度限制和日志格式;HTTP/2 下的头压缩对 UA 长度的影响;urllib.robotparser 以外的 robots 解析器(如 Protego)对 UA 的匹配方式'],
    'User-Agent 与日志')
